{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (1, 3), (2, 5), (3, 6), (10, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_transcript_values_whitespace_and_skipped_lines():
    lines = ["", "  \n", "  # comment,with,commas", "  x , -3 , 1  ",
             " y, 4, 0 ", "z, 5,   "]
    assert parse_transcript_log(lines) == [
        event("x", -3, True), event("y", 4, False), event("z", 5, None)
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1,yes"])
def test_parse_transcript_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["  ", " # comment", "x,1,0", bad_line])


def test_dedupe_keeps_last_duplicate_id_then_sorts_by_day_and_id():
    events = [event("x", 1, True), event("b", 2, True), event("a", 2, False),
              event("x", 3, None), event("b", 2, False)]
    assert dedupe_transcripts(events) == [events[2], events[4], events[3]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_fills_gaps_and_respects_range():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_calendar_days_pooling_rounding_and_nonempty_groups():
    groups = {
        "a": [event("a", 1, True)],
        "b": [event("b", 4, False), event("c", 4, False), event("d", 4, False),
              event("e", 4, False), event("f", 4, False)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.167, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"flagged": True}], "empty": [], "a": [{"flagged": True}],
              "b": [{"flagged": False}]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [{"flagged": None}], "a": [{"flagged": True}]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_resets_on_zero_and_negative():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([1, 0, 1, 0, 1]) == 1
    assert longest_flag_streak([-1, 0]) == 0
    assert longest_flag_streak([]) == 0
